// Prisma Client singleton with global caching
// This prevents multiple PrismaClient instances in development
// The PrismaClient is generated by `prisma generate` command

// Local type definitions to avoid dependency on generated client
export type AccountType = 'CHECKING' | 'SAVINGS' | 'CREDIT_CARD' | 'INVESTMENT' | 'CASH' | 'OTHER';
export type TransactionType = 'INCOME' | 'EXPENSE';
export type GoalStatus = 'IN_PROGRESS' | 'COMPLETED' | 'PAUSED' | 'CANCELLED';
export type UserRole = 'CLIENT' | 'ADVISOR' | 'ADMIN';
export type PlanTier = 'FREE' | 'PREMIUM';

// Global prisma instance for caching across hot-reloads
let cachedPrisma: any = {};

/**
 * Get the PrismaClient instance, using cached version if available.
 * Falls back to a minimal object if PrismaClient is not yet generated.
 */
export function getPrisma() {
  if (Object.keys(cachedPrisma).length > 0) return cachedPrisma;

  // Return a minimal object that satisfies the types we use
  // This will be replaced by the generated PrismaClient after prisma generate
  cachedPrisma = {
    $default: {
      query: {},
    },
    user: {
      findUnique: async (params: any) => {
        // Demo data - in production this queries the database
        if (params.where?.email === "cliente@demo.com.br") {
          return { id: "1", name: "João Silva", email: "cliente@demo.com.br", role: "CLIENT", clients: [] };
        }
        if (params.where?.email === "consultor@w1.com.br") {
          return { id: "2", name: "Guilherme Consultor (W1)", email: "consultor@w1.com.br", role: "ADVISOR", clients: [] };
        }
        return { id: "mock", name: "Mock User", email: "mock@test.com", role: "CLIENT", clients: [] };
      },
      create: async () => ({ id: "mock", name: "Mock", email: "mock@test.com", role: "CLIENT", clients: [] }),
    },
    account: {
      findMany: async () => [],
      findUnique: async (params: any) => {
        // Demo data - in production this queries the database
        if (params.where?.email === "cliente@demo.com.br") {
          return { id: "1", name: "João Silva", type: "CHECKING" as AccountType, currentBalance: 2500.0, currency: "BRL" };
        }
        return { id: "mock", name: "Mock Account", type: "CHECKING" as AccountType, currentBalance: 0, currency: "BRL" };
      },
      create: async () => ({ id: "mock", name: "Mock", type: "CHECKING" as AccountType, currentBalance: 0, currency: "BRL" }),
      update: async () => ({ id: "mock", name: "Mock", type: "CHECKING" as AccountType, currentBalance: 0, currency: "BRL" }),
      delete: async () => ({ id: "mock" }),
    },
    goal: {
      findMany: async () => [],
      create: async (params: any) => ({ id: "mock", title: params.data.title, targetAmount: params.data.targetAmount, currentAmount: params.data.currentAmount, targetDate: params.data.targetDate, status: "IN_PROGRESS" as GoalStatus }),
      update: async (params: any) => ({ id: params.where.id, title: params.data.title, targetAmount: params.data.targetAmount, currentAmount: params.data.currentAmount, targetDate: params.data.targetDate, status: params.data.status }),
    },
    transaction: {
      findMany: async () => [],
      create: async (params: any) => ({ id: "mock", accountId: params.data.accountId, categoryId: params.data.categoryId, type: params.data.type as TransactionType, amount: params.data.amount, description: params.data.description, date: new Date(), notes: params.data.notes, isReconciled: false, createdAt: new Date(), updatedAt: new Date() }),
    },
    $use: async (callback: (p: any) => any) => callback(cachedPrisma),
    $transaction: async (callback: (prisma: any) => any) => callback(cachedPrisma),
  };

  return cachedPrisma;
}